from typing import no_type_check

from tilus.hidet.ir.dtypes import uint8
from tilus.hidet.ir.dtypes import uint32 as uint32_dt
from tilus.hidet.ir.dtypes import uint64 as uint64_dt
from tilus.hidet.ir.primitives.func import call_primitive_func
from tilus.hidet.ir.primitives.utils import register_primitive_function_decorator


@initialize()
def register_wgmma_encode_smem_descriptor():
    from tilus.hidet.lang import attrs
    from tilus.hidet.lang import script as script_fn

    @register_primitive_function_decorator
    @no_type_check
    @script_fn
    def wgmma_encode_smem_descriptor(
        smem_addr: uint32_dt,  # 14 bits
        lbo: uint32_dt,  # 14 bits
        sbo: uint32_dt,  # 14 bits
        mbo: uint8,  # 3 bits
        swizzle_mode: uint8,  # 2 bits
    ) -> uint64_dt:
        attrs.func_name = "cuda_wgmma_encode_smem_descriptor"
        attrs.func_kind = "cuda_internal"
        desc: uint64_dt = uint64_dt(0)
        desc = desc | uint64_dt(lbo & uint32_dt(0x3FFF)) << 16
        desc = desc | uint64_dt(sbo & uint32_dt(0x3FFF)) << 32
        desc = desc | uint64_dt(mbo & uint8(0b111)) << 49
        desc = desc | uint64_dt(swizzle_mode & uint8(0b11)) << 62
        desc = desc | uint64_dt(smem_addr & uint32_dt(0x3FFF))
        return desc


def wgmma_encode_smem_descriptor(
    smem_addr,
    lbo,
    sbo,
    mbo,
    swizzle_mode,
) -> Expr:
    func_name = "cuda_wgmma_encode_smem_descriptor"
    return call_primitive_func(
        func_name, [uint32_dt(smem_addr), uint32_dt(lbo), uint32_dt(sbo), uint8(mbo), uint8(swizzle_mode)]
    )
